# Block 1259, across Eastern Parkway from the site, Franklin Avenue to
# Bedford Avenue: its lots, dissolved into one outline.
return curio_load_data("data.nyc.crown-heights-1550-bedford", part="block-1259.geojson")

{
  "compute": [
    {
      "dataRef": "[!! input_0 !!]",
      "attributes": {
        "x": "properties.x",
        "y": "properties.y"
      },
      "uniforms": {
        "tallest": {
          "fromFeature": {
            "layer": "[!! input_1 !!]",
            "path": "properties.tallest"
          }
        }
      },
      "uniformMatrices": {
        "heights": {
          "fromFeature": {
            "layer": "[!! input_1 !!]",
            "path": "properties.heights"
          }
        },
        "steps": {
          "fromFeature": {
            "layer": "[!! input_2 !!]",
            "path": "properties.steps"
          },
          "cols": 4
        }
      },
      "outputColumnName": "shadow_min",
      "wglsFunction": [
        "// Minutes this ground cell spends in shadow over the day: at each step",
        "// (steps: toward east, toward north, cot of the elevation, minutes), the",
        "// ray from the cell toward the sun across the heights grid. A cell under",
        "// a roof in this scenario gets -1, and the next node leaves it out.",
        "let own = heights[u32(floor(y / 3.0)) * heights_cols + u32(floor(x / 3.0))];",
        "if (own > 0.0) { return -1.0; }",
        "var total: f32 = 0.0;",
        "for (var s = 0u; s < steps_rows; s++) {",
        "    let sx = steps[s * 4u];",
        "    let sy = steps[s * 4u + 1u];",
        "    let cot = steps[s * 4u + 2u];",
        "    var shaded = false;",
        "    for (var t: f32 = 1.5; t <= tallest * cot; t += 1.5) {",
        "        let col = i32(floor((x + sx * t) / 3.0));",
        "        let row = i32(floor((y + sy * t) / 3.0));",
        "        if (col < 0 || row < 0 || col >= i32(heights_cols) || row >= i32(heights_rows)) { break; }",
        "        if (heights[u32(row) * heights_cols + u32(col)] * cot > t) { shaded = true; break; }",
        "    }",
        "    if (shaded) { total += steps[s * 4u + 3u]; }",
        "}",
        "return total;"
      ]
    }
  ]
}

{
  "compute": [
    {
      "dataRef": "[!! input_0 !!]",
      "attributes": {
        "sx": "properties.east",
        "sy": "properties.north",
        "cot": "properties.cot"
      },
      "uniforms": {
        "tallest": {
          "fromFeature": {
            "layer": "[!! input_1 !!]",
            "path": "properties.tallest"
          }
        }
      },
      "uniformMatrices": {
        "heights": {
          "fromFeature": {
            "layer": "[!! input_1 !!]",
            "path": "properties.heights"
          }
        },
        "spots": {
          "fromFeature": {
            "layer": "[!! input_1 !!]",
            "path": "properties.spots"
          },
          "cols": 2
        }
      },
      "outputColumnName": "share",
      "wglsFunction": [
        "// The share of Block 1259's open ground in shadow at this step (in %):",
        "// from each of its spots (spots: x, y), the ray toward the sun, marched",
        "// across the heights grid as on the map.",
        "var dark: f32 = 0.0;",
        "for (var p = 0u; p < spots_rows; p++) {",
        "    let px = spots[p * 2u];",
        "    let py = spots[p * 2u + 1u];",
        "    var shaded = false;",
        "    for (var t: f32 = 1.5; t <= tallest * cot; t += 1.5) {",
        "        let col = i32(floor((px + sx * t) / 3.0));",
        "        let row = i32(floor((py + sy * t) / 3.0));",
        "        if (col < 0 || row < 0 || col >= i32(heights_cols) || row >= i32(heights_rows)) { break; }",
        "        if (heights[u32(row) * heights_cols + u32(col)] * cot > t) { shaded = true; break; }",
        "    }",
        "    if (shaded) { dark += 1.0; }",
        "}",
        "return 100.0 * dark / f32(max(spots_rows, 1u));"
      ]
    }
  ]
}

{
  "compute": [
    {
      "dataRef": "[!! input_0 !!]",
      "attributes": {
