{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "[!! inputs !!]"
  },
  "layer": [
    {
      "mark": {
        "type": "line",
        "point": true
      },
      "encoding": {
        "x": {
          "field": "time",
          "type": "temporal",
          "scale": {
            "type": "utc"
          },
          "axis": {
            "format": "%-I %p",
            "tickMinStep": 3600000
          },
          "title": null
        },
        "y": {
          "field": "share",
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              100
            ]
          },
          "title": "In shadow (%)"
        },
        "color": {
          "field": "scenario_name",
          "type": "nominal",
          "title": "Scenario",
          "scale": [!! scenario colors !!],
          "sort": [!! scenario order !!],
          "legend": {
            "orient": "top",
            "direction": "vertical",
            "title": null,
            "labelLimit": 0
          }
        },
        "strokeWidth": {
          "field": "scenario_name",
          "type": "nominal",
          "sort": [!! scenario order !!],
          "scale": {
            "range": [
              5,
              2
            ]
          }
        },
        "tooltip": [
          {
            "field": "scenario_name",
            "type": "nominal",
            "title": "Scenario"
          },
          {
            "field": "clock",
            "type": "nominal",
            "title": "Time"
          },
          {
            "field": "share",
            "type": "quantitative",
            "title": "In shadow (%)",
            "format": ".0f"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "window": [
            {
              "op": "row_number",
              "as": "row"
            }
          ]
        },
        {
          "filter": "datum.row == 1"
        },
        {
          "calculate": "'Counted from ' + datum.window_from + ' to ' + datum.window_to",
          "as": "window"
        }
      ],
      "mark": {
        "type": "text",
        "baseline": "top",
        "fontSize": 11,
        "fontWeight": "bold",
        "color": "#333"
      },
      "encoding": {
        "x": {
          "value": {
            "expr": "width / 2"
          }
        },
        "y": {
          "value": {
            "expr": "height + 22"
          }
        },
        "text": {
          "field": "window",
          "type": "nominal"
        }
      }
    }
  ]
}

